<?php
defined('ABSPATH')||exit;final class SPL_Privacy{public function hooks(){add_filter('wp_privacy_personal_data_exporters',array($this,'exporters'));add_filter('wp_privacy_personal_data_erasers',array($this,'erasers'));}public function exporters($e){$e['pdf-library']=array('exporter_friendly_name'=>'PDF Library Reading Data','callback'=>array($this,'export'));return$e;}public function export($email,$page=1){$u=get_user_by('email',$email);if(!$u)return array('data'=>array(),'done'=>true);global$wpdb;$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}spl_user_data WHERE user_id=%d LIMIT 500",$u->ID));$data=array();foreach($rows as$r)$data[]=array('group_id'=>'pdf-library','group_label'=>'PDF Library','item_id'=>'reading-'.$r->id,'data'=>array(array('name'=>'Document','value'=>get_the_title($r->document_id)),array('name'=>'Type','value'=>$r->data_type),array('name'=>'Page','value'=>$r->page_number),array('name'=>'Private note','value'=>$r->note)));return array('data'=>$data,'done'=>true);}public function erasers($e){$e['pdf-library']=array('eraser_friendly_name'=>'PDF Library Reading Data','callback'=>array($this,'erase'));return$e;}public function erase($email,$page=1){$u=get_user_by('email',$email);if(!$u)return array('items_removed'=>false,'items_retained'=>false,'messages'=>array(),'done'=>true);global$wpdb;$wpdb->delete($wpdb->prefix.'spl_user_data',array('user_id'=>$u->ID));$wpdb->update($wpdb->prefix.'spl_reports',array('user_id'=>0,'details'=>'[Removed through privacy request]'),array('user_id'=>$u->ID));return array('items_removed'=>true,'items_retained'=>false,'messages'=>array(),'done'=>true);}}
